SourceCode.Declaration:
/// <summary>
/// getJournalState's answer. State is OPEN, POSTED or NOT_FOUND - what the app checks before it
/// lets a submitted journal be reopened on the device.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountJournalStateResponse
{
    boolean success;
    str     errorCode;
    str     state;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('State')]
public str parmState(str _value = state)
{
    state = _value;
    return state;
}
